// Rules conformance: every rule ID in rubric/v5-styles.md has one or more made-up outfits that must show the rule
// working in the parts engine (the right check fires or doesn't, the right part moves by the right amount, the score
// lands in the right band). Cases come from fixtures/rules_conformance.json, generated by
// extraction-test/rules_conformance.py against parts_proto.py; the assertion rules below mirror its check() line for
// line. Each test name starts with its rule ID, so a broken rule names itself. If a case fails, the engine broke a
// written rule: fix the engine (or, after a decision, the doc and the case), never the fixture by hand.
import { describe, expect, it } from "vitest";
import { scoreParts, suggestPartsFixes, type PartResult, type PartsResult, type Reading, type SecondLookInput, type Styles } from "../src/index";
import { loadJSON } from "./helpers";

interface CheckRef { check: string; part?: string; points?: number; line?: string }
interface Expect {
  overall?: number; overall_max?: number; band?: string; band_in?: string[]; unscored?: string;
  fired?: CheckRef[]; not_fired?: CheckRef[]; tips?: CheckRef[]; tips_lacks?: CheckRef[];
  part?: Record<string, { score?: number; na?: boolean }>;
  detected_has?: string[]; detected_lacks?: string[]; label?: string | null; label_in?: (string | null)[];
  ceiling?: number | null; occ_deduction?: number; occ_lines_has?: string[]; occ_lines_lacks?: string[];
  cond_deduction?: number; cond_tips?: string[]; floored?: boolean; bonus?: number; penalty?: number;
  /** v10: the fix engine's Next level / tip line (no points): its id, a substring of its line, or an id it must not be. */
  fix_tip?: string; fix_tip_line?: string; fix_tip_lacks?: string;
}
interface Case {
  id: string; rule: string; what: string; reading: Reading; occasion: string; styles: [string, number][];
  boldness: string; second_look: SecondLookInput | null; expect: Expect;
  vs: { case: string; parts?: Record<string, number>; overall?: number | "up" | "down" | "same" } | null;
  future: string[]; kd: string | null;
  python: { overall: number | null; reason?: string; raw_score?: number; parts?: Record<string, number | null>;
    detected_styles?: string[]; style_label?: string | null; next_level?: { id: string; line: string } | null };
}
interface Conformance { parts_version: string; engine: string; bands: [number, string][]; counts: { cases: number; rules: number };
  rules: string[]; cases: Case[] }

const D = loadJSON<Conformance>("rules_conformance.json");
const EPS = 1e-6;
const bandOf = (x: number): string => D.bands.find(([top]) => x <= top)![1];

function run(c: Case): PartsResult {
  return scoreParts(c.reading, { occasion: c.occasion, styles: c.styles as Styles, boldness: c.boldness, secondLook: c.second_look });
}
const results = new Map<string, PartsResult>(D.cases.map((c) => [c.id, run(c)]));

/** The fix engine's Next level / tip line for a case (no closet, not a warm day, not the first check). */
const fixNextLevel = (c: Case) =>
  suggestPartsFixes(c.reading, { occasion: c.occasion, styles: c.styles as Styles, boldness: c.boldness, secondLook: c.second_look }).nextLevel;

const partsOf = (r: PartsResult): [string, PartResult][] => Object.entries(r.parts ?? {}) as [string, PartResult][];
const reasons = (r: PartsResult, part?: string) =>
  partsOf(r).filter(([k]) => part === undefined || k === part).flatMap(([, p]) => p.reasons);
const tips = (r: PartsResult, part?: string) =>
  partsOf(r).filter(([k]) => part === undefined || k === part).flatMap(([, p]) => p.tips);
const scoreOf = (r: PartsResult, k: string): number | null => (r.parts as Record<string, PartResult | undefined>)[k]?.score ?? null;

/** The same assertion rules as rules_conformance.py check(). Returns the failures. */
function check(c: Case, r: PartsResult): string[] {
  const e = c.expect;
  const bad: string[] = [];
  if (e.unscored !== undefined) {
    if (r.overall !== null || r.reason !== e.unscored) bad.push(`unscored: want ${e.unscored}, got ${r.overall}`);
    return bad;
  }
  if (r.overall === null) return [`unscored (${r.reason})`];
  const ov = r.overall;
  if (e.overall !== undefined && Math.abs(ov - e.overall) > EPS) bad.push(`overall ${ov} != ${e.overall}`);
  if (e.overall_max !== undefined && ov > e.overall_max + EPS) bad.push(`overall ${ov} > ${e.overall_max}`);
  if (e.band !== undefined && bandOf(ov) !== e.band) bad.push(`band ${bandOf(ov)} (${ov}) != ${e.band}`);
  if (e.band_in !== undefined && !e.band_in.includes(bandOf(ov))) bad.push(`band ${bandOf(ov)} (${ov}) not in ${e.band_in}`);
  for (const f of e.fired ?? []) {
    const hits = reasons(r, f.part).filter((x) => x.check === f.check);
    if (!hits.length) bad.push(`${f.check} didn't fire${f.part ? " on " + f.part : ""}`);
    else if (f.points !== undefined && !hits.some((x) => Math.abs(x.points - f.points!) < EPS))
      bad.push(`${f.check} moved ${hits.map((x) => x.points)}, want ${f.points}`);
    else if (f.line !== undefined && !hits.some((x) => x.line.includes(f.line!)))
      bad.push(`${f.check} line ${JSON.stringify(hits.map((x) => x.line))} lacks '${f.line}'`);
  }
  for (const f of e.not_fired ?? []) if (reasons(r, f.part).some((x) => x.check === f.check)) bad.push(`${f.check} fired`);
  for (const f of e.tips ?? []) if (!tips(r, f.part).some((x) => x.check === f.check)) bad.push(`tip ${f.check} missing`);
  for (const f of e.tips_lacks ?? []) if (tips(r, f.part).some((x) => x.check === f.check)) bad.push(`tip ${f.check} present`);
  for (const [k, want] of Object.entries(e.part ?? {})) {
    const s = scoreOf(r, k);
    if (want.na) { if (s !== null) bad.push(`${k} scored ${s}, want NA`); }
    else if (want.score !== undefined && (s === null || Math.abs(s - want.score) > EPS)) bad.push(`${k} ${s} != ${want.score}`);
  }
  const det: string[] = r.detectedStyles;
  for (const s of e.detected_has ?? []) if (!det.includes(s)) bad.push(`${s} not detected (${det})`);
  for (const s of e.detected_lacks ?? []) if (det.includes(s)) bad.push(`${s} detected (${det})`);
  if (e.label !== undefined && r.styleLabel !== e.label) bad.push(`label ${r.styleLabel} != ${e.label}`);
  if (e.label_in !== undefined && !e.label_in.includes(r.styleLabel)) bad.push(`label ${r.styleLabel} not in ${e.label_in}`);
  const occ = r.occasion;
  if (e.ceiling !== undefined) {
    const got = occ.ceiling;
    if ((got === null) !== (e.ceiling === null) || (got !== null && Math.abs(got - e.ceiling!) > 1e-3))
      bad.push(`ceiling ${got} != ${e.ceiling}`);
  }
  if (e.occ_deduction !== undefined && Math.abs(occ.deduction - e.occ_deduction) > 1e-3)
    bad.push(`occasion deduction ${occ.deduction} != ${e.occ_deduction}`);
  for (const s of e.occ_lines_has ?? []) if (!occ.lines.some((l) => l.includes(s))) bad.push(`occasion line '${s}' missing`);
  for (const s of e.occ_lines_lacks ?? []) if (occ.lines.some((l) => l.includes(s))) bad.push(`occasion line '${s}' present`);
  if (e.cond_deduction !== undefined && Math.abs(r.condition.deduction - e.cond_deduction) > 1e-3)
    bad.push(`condition ${r.condition.deduction} != ${e.cond_deduction}`);
  if (e.cond_tips !== undefined && JSON.stringify(r.condition.tips.map((x) => x.check)) !== JSON.stringify(e.cond_tips))
    bad.push(`condition tips ${JSON.stringify(r.condition.tips.map((x) => x.check))} != ${JSON.stringify(e.cond_tips)}`);
  if (e.floored !== undefined && r.floored !== e.floored) bad.push(`floored ${r.floored} != ${e.floored}`);
  if (e.bonus !== undefined && Math.abs(r.earnedBonus - e.bonus) > EPS) bad.push(`bonus ${r.earnedBonus} != ${e.bonus}`);
  if (e.penalty !== undefined && Math.abs(r.piledPenalty - e.penalty) > EPS) bad.push(`penalty ${r.piledPenalty} != ${e.penalty}`);
  if (e.fix_tip !== undefined || e.fix_tip_lacks !== undefined) {
    const nl = fixNextLevel(c);
    if (e.fix_tip !== undefined && nl?.id !== e.fix_tip) bad.push(`fix tip ${nl?.id} != ${e.fix_tip}`);
    if (e.fix_tip !== undefined && e.fix_tip_line !== undefined && !(nl?.line ?? "").includes(e.fix_tip_line))
      bad.push(`fix tip line ${nl?.line} lacks '${e.fix_tip_line}'`);
    if (e.fix_tip_lacks !== undefined && nl?.id === e.fix_tip_lacks) bad.push(`fix tip ${e.fix_tip_lacks} shown`);
  }
  if (c.vs) {
    const b = results.get(c.vs.case)!;
    for (const [k, d] of Object.entries(c.vs.parts ?? {})) {
      const a = scoreOf(r, k), z = scoreOf(b, k);
      if (a === null || z === null) bad.push(`vs ${c.vs.case}: ${k} is NA`);
      else if (Math.abs(a - z - d) > EPS) bad.push(`vs ${c.vs.case}: ${k} moved ${(a - z).toFixed(3)}, want ${d}`);
    }
    const want = c.vs.overall;
    if (want !== undefined) {
      const delta = ov - (b.overall ?? NaN);
      const ok = want === "up" ? delta > EPS : want === "down" ? delta < -EPS : want === "same" ? Math.abs(delta) < EPS
        : Math.abs(delta - want) < EPS;
      if (!ok) bad.push(`vs ${c.vs.case}: overall moved ${delta}, want ${want}`);
    }
  }
  return bad;
}

describe("rules conformance (rubric/v5-styles.md)", () => {
  it("covers every rule ID with at least one case", () => {
    expect(D.cases.length).toBe(D.counts.cases);
    expect(new Set(D.cases.map((c) => c.rule)).size).toBe(D.counts.rules);
    expect([...new Set(D.cases.map((c) => c.rule))].sort()).toEqual(D.rules);
  });

  for (const c of D.cases) {
    const name = `${c.rule} ${c.id}: ${c.what}${c.kd ? ` [${c.kd}]` : ""}${c.future.length ? " (future values)" : ""}`;
    it(name, () => {
      const r = results.get(c.id)!;
      expect(check(c, r)).toEqual([]);
      // and the same result as Python on the numbers the rule leans on
      expect(r.overall).toBe(c.python.overall);
      if (r.overall !== null) {
        expect(Math.abs(r.rawScore - c.python.raw_score!)).toBeLessThan(1e-9);
        for (const [k, v] of Object.entries(c.python.parts ?? {})) expect(scoreOf(r, k)).toBe(v);
        expect(r.detectedStyles).toEqual(c.python.detected_styles);
        expect(r.styleLabel).toBe(c.python.style_label);
        if (c.python.next_level !== undefined) {
          const nl = fixNextLevel(c);
          expect(nl === null ? null : { id: nl.id, line: nl.line }).toEqual(c.python.next_level === null ? null : { id: c.python.next_level.id, line: c.python.next_level.line });
        }
      }
    });
  }
});
